      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Colorectal laterally spreading tumors (LSTs) larger than 20 mm are significant precursors to colorectal cancer. Endoscopic submucosal dissection (ESD) and endoscopic mucosal resection (EMR) are widely used treatments, but their comparative efficacy and safety remain controversial.",
      "reason": "The text describes the current state of knowledge regarding the treatment of colorectal laterally spreading tumors and identifies the uncertainty regarding the comparative efficacy and safety of ESD and EMR."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "This systematic review and meta-analysis aimed to compare ESD and EMR in terms of local recurrence, perforation, and delayed bleeding for colorectal LSTs > 20 mm.",
      "reason": "The text explains the need for the review by stating the aim to compare the two techniques regarding specific clinical outcomes due to the existing controversy."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention the existence of similar systematic reviews, therefore this requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review evaluates procedural endoscopic techniques (ESD and EMR) rather than pharmacological or other interventions with a biological mechanism of action."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The intervention is not a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 100
